<script setup lang="ts">import{computed,ref,useSlots,watch}from'vue';import{useZtSize}from'../config-provider/context';import ZtIcon from'../icon/ZtIcon.vue';import type{ZtAvatarProps}from'./types';import'./avatar.scss';defineOptions({name:'ZtAvatar'});const props=withDefaults(defineProps<ZtAvatarProps>(),{shape:'circle',fit:'cover',status:'default'});const emit=defineEmits<{load:[event:Event];error:[event:Event]}>(),failed=ref(false),slots=useSlots(),inherited=useZtSize(props as never);watch(()=>[props.src,props.srcSet],()=>failed.value=false);const preset=computed(()=>typeof props.size==='string'&&['mini','small','default','medium','large'].includes(props.size)?props.size:typeof props.size==='number'?undefined:props.size?undefined:inherited.value);const custom=computed(()=>typeof props.size==='number'&&props.size>0?`${props.size}px`:typeof props.size==='string'&&!preset.value?props.size:undefined);const initial=computed(()=>Array.from(props.alt?.trim()||'')[0]);</script>
<template><span class="zt-avatar" :class="[`zt-avatar--${shape}`,`zt-avatar--${status}`,preset&&`zt-avatar--${preset}`]" :style="custom?{'--zt-avatar-size':custom}:undefined" :aria-label="alt||undefined"><img v-if="src&&!failed" :src="src" :srcset="srcSet" :alt="alt||''" :style="{objectFit:fit}" @load="emit('load',$event)" @error="failed=true;emit('error',$event)"><slot v-else-if="slots.default" /><ZtIcon v-else-if="icon" :name="typeof icon==='string'?icon:undefined" :component="typeof icon==='string'?undefined:icon"/><span v-else-if="initial">{{initial}}</span><ZtIcon v-else name="user" /></span></template>
